CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Summary of Sales by Year` AS select `Orders`.`ShippedDate` AS `ShippedDate`,`Orders`.`OrderID` AS `OrderID`,`Order Subtotals`.`Subtotal` AS `Subtotal` from (`Orders` join `Order Subtotals` on((`Orders`.`OrderID` = `Order Subtotals`.`OrderID`))) where (`Orders`.`ShippedDate` is not null);
